      numberSample: { name: "number_sample", detail: "Obligatoire. Repr\xE9sente la taille de l\u2019\xE9chantillon." },
      populationS: { name: "population_s", detail: "Obligatoire. Repr\xE9sente le nombre de succ\xE8s de la population." },
      numberPop: { name: "number_pop", detail: "Obligatoire. Repr\xE9sente la taille de la population." },
